sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cah-hero {
  min-height: 600px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  /* Modern SaaS gradient background */
  background: linear-gradient(180deg, #F8FAFC 0%, #FFFFFF 100%);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  position: relative;
  overflow: hidden;
}

/* Subtle decorative blur blob */
.cah-hero::before {
  content: "";
  position: absolute;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 400px;
  background: radial-gradient(circle, rgba(37,99,235,0.06) 0%, rgba(255,255,255,0) 70%);
  z-index: 0;
  pointer-events: none;
}

.hero-content {
  max-width: 900px;
  padding: 80px 20px;
  z-index: 1;
  position: relative;
}

.hero-badge {
  display: inline-block;
  padding: 8px 18px;
  margin-bottom: 24px;
  background: #EEF2FF;
  color: #4F46E5;
  border: 1px solid #E0E7FF;
  border-radius: 9999px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.5px;
  box-shadow: 0 2px 4px rgba(79, 70, 229, 0.05);
}

.hero-content h1 {
  margin: 0;
  color: #0F172A;
  font-size: 64px;
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1.1;
}

.hero-content h1 span {
  display: block;
  background: linear-gradient(to right, #2563EB, #4F46E5);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-content p {
  max-width: 680px;
  margin: 32px auto;
  color: #475569;
  font-size: 20px;
  font-weight: 400;
  line-height: 1.6;
}

.hero-buttons {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin-top: 40px;
}

.hero-buttons button {
  border: none;
  padding: 16px 32px;
  border-radius: 12px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  align-items: center;
  gap: 8px;
}

.hero-buttons button .glyphicon {
  font-size: 14px;
}

.hero-buttons .primary-btn {
  background: #2563EB;
  color: white;
  box-shadow: 0 4px 6px -1px rgba(37, 99, 235, 0.2), 0 2px 4px -1px rgba(37, 99, 235, 0.1);
}

.hero-buttons .primary-btn:hover {
  background: #1D4ED8;
  transform: translateY(-2px);
  box-shadow: 0 10px 15px -3px rgba(37, 99, 235, 0.25), 0 4px 6px -2px rgba(37, 99, 235, 0.1);
}

.hero-buttons .secondary-btn {
  background: #FFFFFF;
  color: #334155;
  border: 1px solid #E2E8F0;
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.06);
}

.hero-buttons .secondary-btn:hover {
  background: #F8FAFC;
  border-color: #CBD5E1;
  transform: translateY(-2px);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.hero-users {
  margin-top: 40px;
  color: #64748B;
  font-size: 14px;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.hero-users span {
  color: #CBD5E1;
}

@media (max-width: 768px) {
  .hero-content h1 {
    font-size: 42px;
  }
  .hero-buttons {
    flex-direction: column;
    width: 100%;
  }
  .hero-buttons button {
    width: 100%;
    justify-content: center;
  }
}
